252: {
253: #if defined(__linux__) && defined(REACTOR_ANONYMOUS_MMAP_NAME)
254: 	free(memory);
255: #else
256: 	if(memory)
257: 	{
258: 		unsigned char *aligned = (unsigned char *)memory;
259: 		Allocation *allocation = (Allocation *)(aligned - sizeof(Allocation));
260: 
261: 		delete[] allocation->block;
262: 	}
263: #endif
264: }
